class Solution:
    def isPrefixOfWord(self, sentence, searchWord):
        def KMP(text, pattern):
            def getPrefix(pattern):
                prefix = [-1] * len(pattern)
                j = -1
                for i in range(1, len(pattern)):
                    while j > -1 and pattern[j + 1] != pattern[i]:
                        j = prefix[j]
                    if pattern[j + 1] == pattern[i]:
                        j += 1
                    prefix[i] = j
                return prefix

            prefix = getPrefix(pattern)
            j = -1
            for i in range(len(text)):
                while j != -1 and pattern[j+1] != text[i]:
                    j = prefix[j]
                if pattern[j+1] == text[i]:
                    j += 1
                if j+1 == len(pattern):
                    return i-j
            return -1

        if sentence.startswith(searchWord):
            return 1
        p = KMP(sentence, ' ' + searchWord)
        if p == -1:
            return -1
        return 1+sum(sentence[i] == ' ' for i in range(p+1))

class Solution:
    def maxVowels(self, s: str, k: int) -> int:

        def find_count_vowels(string):
            lst_vowels= ['a', 'e', 'i', 'o', 'u']
            c=0
            for i in string:
                if i in lst_vowels:
                    c+=1
            return c


        lst_vowels= ['a', 'e', 'i', 'o', 'u']
        if k>len(s):
            return find_count_vowels(s)
        dp = [0]*(len(s)-k+1)
        dp[0] = find_count_vowels(s[:k])
        for i in range(1,len(s)-k+1):


            if s[i-1] in lst_vowels and s[i+k-1] in lst_vowels:
                dp[i] = dp[i-1]
            elif s[i-1] in lst_vowels and s[i+k-1] not in lst_vowels:
                dp[i] = dp[i-1] - 1

            elif s[i-1] not in lst_vowels and s[i+k-1] in lst_vowels:
                dp[i] = dp[i-1] + 1
            else:
                dp[i] = dp[i-1]
        return max(dp)

class Solution:
    def maxVowels(self, s: str, k: int) -> int:
        VOWELS = set("aeiou")
        result = curr = 0
        for i, c in enumerate(s):
            curr += c in VOWELS
            if i >= k:
                curr -= s[i-k] in VOWELS
            result = max(result, curr)
        return result

class Solution:
    def maxDotProduct(self, A, B):
        dp = [float('-inf')] * (len(B)+1)
        for i in range(len(A)):
            prev = float('-inf')
            for j in range(len(B)):
                product = A[i] * B[j]
                prev, dp[j+1] = dp[j+1], max(dp[j+1], dp[j], product, prev + product)
        return dp[-1]

class Solution:
    def maxDotProduct(self, nums1, nums2):
        if len(nums1) < len(nums2):
            return self.maxDotProduct(nums2, nums1)
        dp = [[0]*len(nums2) for i in range(2)]
        for i in range(len(nums1)):
            for j in range(len(nums2)):
                dp[i%2][j] = nums1[i]*nums2[j]
                if i and j:
                    dp[i%2][j] += max(dp[(i-1)%2][j-1], 0)
                if i:
                    dp[i%2][j] = max(dp[i%2][j], dp[(i-1)%2][j])
                if j:
                    dp[i%2][j] = max(dp[i%2][j], dp[i%2][j-1])
        return dp[(len(nums1)-1)%2][-1]

