class Solution:
    def hasAllCodes(self, s: str, k: int) -> bool:
        lookup = set()
        base = 2**k
        if base > len(s):
            return False
        num = 0
        for i in range(len(s)):
            num = (num << 1) + (s[i] == '1')
            if i >= k-1:
                lookup.add(num)
                num -= (s[i-k+1] == '1') * (base//2)
        return len(lookup) == base

